def SKQCreateTRACKSVector(builder, data):
    data = list(data)
    builder.StartVector(48, len(data), 8)
    for item in reversed(data):
        item.Pack(builder)
    return builder.EndVector()

def CreateTRACKSVector(builder, data):
    SKQCreateTRACKSVector(builder, data)

def SKQAddPOINTINGS(builder, POINTINGS):
    builder.PrependUOffsetTRelativeSlot(27, flatbuffers.number_types.UOffsetTFlags.py_type(POINTINGS), 0)

def AddPOINTINGS(builder, POINTINGS):
    SKQAddPOINTINGS(builder, POINTINGS)

def SKQStartPOINTINGSVector(builder, numElems):
    return builder.StartVector(24, numElems, 8)

def StartPOINTINGSVector(builder, numElems):
    return SKQStartPOINTINGSVector(builder, numElems)

def SKQCreatePOINTINGSVector(builder, data):
    data = list(data)
    builder.StartVector(24, len(data), 8)
    for item in reversed(data):
        item.Pack(builder)
    return builder.EndVector()

def CreatePOINTINGSVector(builder, data):
    SKQCreatePOINTINGSVector(builder, data)

def SKQAddEXCLUSION_RADIUS_DEG(builder, EXCLUSION_RADIUS_DEG):
    builder.PrependFloat64Slot(28, EXCLUSION_RADIUS_DEG, float('nan'))

def AddEXCLUSION_RADIUS_DEG(builder, EXCLUSION_RADIUS_DEG):
    SKQAddEXCLUSION_RADIUS_DEG(builder, EXCLUSION_RADIUS_DEG)

def SKQAddMAG_THRESHOLD(builder, MAG_THRESHOLD):
    builder.PrependFloat32Slot(29, MAG_THRESHOLD, float('nan'))

def AddMAG_THRESHOLD(builder, MAG_THRESHOLD):
    SKQAddMAG_THRESHOLD(builder, MAG_THRESHOLD)

def SKQEnd(builder):
    return builder.EndObject()

def End(builder):
    return SKQEnd(builder)

import SKQDetection
import SKQPointing
import SKQTrack
try:
    from typing import List
except:
    pass

class SKQT(object):

    # SKQT
    def __init__(
        self,
        QUERY_ID = None,
        QUERY_KIND = 0,
        EPOCH_JD_TT = float('nan'),
        EPOCH_JD_TT_FRACTION = 0.0,
        OBSERVER_ID = None,
        OBSERVER_POSITION_M = None,
        OBSERVER_VELOCITY_M_PER_S = None,
        PLACE = 3,
        BAND_ID = None,
        MAG_LIMIT = float('nan'),
        MAX_RESULTS = 0,
        TILE_ORDER = 3,
        COLOR_ENCODING = 0,
        COLOR_BLUE_BAND_ID = None,
        COLOR_RED_BAND_ID = None,
        LAYER_ID = None,
        BAND_IDS = None,
        RA_DEG = float('nan'),
        DEC_DEG = float('nan'),
        RADIUS_DEG = float('nan'),
        HALF_WIDTH_DEG = float('nan'),
        HALF_HEIGHT_DEG = float('nan'),
        ROLL_DEG = 0.0,
        DETECTIONS = None,
        TOLERANCE_ARCSEC = float('nan'),
        MAX_FIELD_DEG = float('nan'),
        TRACKS = None,
        POINTINGS = None,
        EXCLUSION_RADIUS_DEG = float('nan'),
        MAG_THRESHOLD = float('nan'),
    ):
        self.QUERY_ID = QUERY_ID  # type: Optional[str]
        self.QUERY_KIND = QUERY_KIND  # type: int
        self.EPOCH_JD_TT = EPOCH_JD_TT  # type: float
        self.EPOCH_JD_TT_FRACTION = EPOCH_JD_TT_FRACTION  # type: float
        self.OBSERVER_ID = OBSERVER_ID  # type: Optional[str]
        self.OBSERVER_POSITION_M = OBSERVER_POSITION_M  # type: Optional[List[float]]
        self.OBSERVER_VELOCITY_M_PER_S = OBSERVER_VELOCITY_M_PER_S  # type: Optional[List[float]]
        self.PLACE = PLACE  # type: int
        self.BAND_ID = BAND_ID  # type: Optional[str]
        self.MAG_LIMIT = MAG_LIMIT  # type: float
        self.MAX_RESULTS = MAX_RESULTS  # type: int
        self.TILE_ORDER = TILE_ORDER  # type: int
        self.COLOR_ENCODING = COLOR_ENCODING  # type: int
        self.COLOR_BLUE_BAND_ID = COLOR_BLUE_BAND_ID  # type: Optional[str]
        self.COLOR_RED_BAND_ID = COLOR_RED_BAND_ID  # type: Optional[str]
        self.LAYER_ID = LAYER_ID  # type: Optional[str]
        self.BAND_IDS = BAND_IDS  # type: Optional[List[Optional[str]]]
        self.RA_DEG = RA_DEG  # type: float
        self.DEC_DEG = DEC_DEG  # type: float
        self.RADIUS_DEG = RADIUS_DEG  # type: float
        self.HALF_WIDTH_DEG = HALF_WIDTH_DEG  # type: float
        self.HALF_HEIGHT_DEG = HALF_HEIGHT_DEG  # type: float
        self.ROLL_DEG = ROLL_DEG  # type: float
        self.DETECTIONS = DETECTIONS  # type: Optional[List[SKQDetection.SKQDetectionT]]
        self.TOLERANCE_ARCSEC = TOLERANCE_ARCSEC  # type: float
        self.MAX_FIELD_DEG = MAX_FIELD_DEG  # type: float
        self.TRACKS = TRACKS  # type: Optional[List[SKQTrack.SKQTrackT]]
        self.POINTINGS = POINTINGS  # type: Optional[List[SKQPointing.SKQPointingT]]
        self.EXCLUSION_RADIUS_DEG = EXCLUSION_RADIUS_DEG  # type: float
        self.MAG_THRESHOLD = MAG_THRESHOLD  # type: float

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpSkq = SKQ()
        tmpSkq.Init(buf, pos)
        return cls.InitFromObj(tmpSkq)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpSkq):
        x = SKQT()
        x._UnPack(tmpSkq)
        return x

    # SKQT
    def _UnPack(self, SKQ):
        if SKQ is None:
            return
        self.QUERY_ID = SKQ.QUERY_ID()
        self.QUERY_KIND = SKQ.QUERY_KIND()
        self.EPOCH_JD_TT = SKQ.EPOCH_JD_TT()
        self.EPOCH_JD_TT_FRACTION = SKQ.EPOCH_JD_TT_FRACTION()
        self.OBSERVER_ID = SKQ.OBSERVER_ID()
        if not SKQ.OBSERVER_POSITION_MIsNone():
            if np is None:
                self.OBSERVER_POSITION_M = []
                for i in range(SKQ.OBSERVER_POSITION_MLength()):
                    self.OBSERVER_POSITION_M.append(SKQ.OBSERVER_POSITION_M(i))
            else:
                self.OBSERVER_POSITION_M = SKQ.OBSERVER_POSITION_MAsNumpy()
        if not SKQ.OBSERVER_VELOCITY_M_PER_SIsNone():
            if np is None:
                self.OBSERVER_VELOCITY_M_PER_S = []
                for i in range(SKQ.OBSERVER_VELOCITY_M_PER_SLength()):
                    self.OBSERVER_VELOCITY_M_PER_S.append(SKQ.OBSERVER_VELOCITY_M_PER_S(i))
            else:
                self.OBSERVER_VELOCITY_M_PER_S = SKQ.OBSERVER_VELOCITY_M_PER_SAsNumpy()
        self.PLACE = SKQ.PLACE()
        self.BAND_ID = SKQ.BAND_ID()
        self.MAG_LIMIT = SKQ.MAG_LIMIT()
        self.MAX_RESULTS = SKQ.MAX_RESULTS()
        self.TILE_ORDER = SKQ.TILE_ORDER()
        self.COLOR_ENCODING = SKQ.COLOR_ENCODING()
        self.COLOR_BLUE_BAND_ID = SKQ.COLOR_BLUE_BAND_ID()
        self.COLOR_RED_BAND_ID = SKQ.COLOR_RED_BAND_ID()
        self.LAYER_ID = SKQ.LAYER_ID()
        if not SKQ.BAND_IDSIsNone():
            self.BAND_IDS = []
            for i in range(SKQ.BAND_IDSLength()):
                self.BAND_IDS.append(SKQ.BAND_IDS(i))
        self.RA_DEG = SKQ.RA_DEG()
        self.DEC_DEG = SKQ.DEC_DEG()
        self.RADIUS_DEG = SKQ.RADIUS_DEG()
        self.HALF_WIDTH_DEG = SKQ.HALF_WIDTH_DEG()
        self.HALF_HEIGHT_DEG = SKQ.HALF_HEIGHT_DEG()
        self.ROLL_DEG = SKQ.ROLL_DEG()
        if not SKQ.DETECTIONSIsNone():
            self.DETECTIONS = []
            for i in range(SKQ.DETECTIONSLength()):
                if SKQ.DETECTIONS(i) is None:
                    self.DETECTIONS.append(None)
                else:
                    sKQDetection_ = SKQDetection.SKQDetectionT.InitFromObj(SKQ.DETECTIONS(i))
                    self.DETECTIONS.append(sKQDetection_)
        self.TOLERANCE_ARCSEC = SKQ.TOLERANCE_ARCSEC()
        self.MAX_FIELD_DEG = SKQ.MAX_FIELD_DEG()
        if not SKQ.TRACKSIsNone():
            self.TRACKS = []
            for i in range(SKQ.TRACKSLength()):
                if SKQ.TRACKS(i) is None:
                    self.TRACKS.append(None)
                else:
                    sKQTrack_ = SKQTrack.SKQTrackT.InitFromObj(SKQ.TRACKS(i))
                    self.TRACKS.append(sKQTrack_)
        if not SKQ.POINTINGSIsNone():
            self.POINTINGS = []
            for i in range(SKQ.POINTINGSLength()):
                if SKQ.POINTINGS(i) is None:
                    self.POINTINGS.append(None)
                else:
                    sKQPointing_ = SKQPointing.SKQPointingT.InitFromObj(SKQ.POINTINGS(i))
                    self.POINTINGS.append(sKQPointing_)
        self.EXCLUSION_RADIUS_DEG = SKQ.EXCLUSION_RADIUS_DEG()
        self.MAG_THRESHOLD = SKQ.MAG_THRESHOLD()

    # SKQT
    def Pack(self, builder):
        if self.QUERY_ID is not None:
            QUERY_ID = builder.CreateString(self.QUERY_ID)
        if self.OBSERVER_ID is not None:
            OBSERVER_ID = builder.CreateString(self.OBSERVER_ID)
        if self.OBSERVER_POSITION_M is not None:
            if np is not None and type(self.OBSERVER_POSITION_M) is np.ndarray:
                OBSERVER_POSITION_M = builder.CreateNumpyVector(self.OBSERVER_POSITION_M)
            else:
                SKQStartOBSERVER_POSITION_MVector(builder, len(self.OBSERVER_POSITION_M))
                for i in reversed(range(len(self.OBSERVER_POSITION_M))):
                    builder.PrependFloat64(self.OBSERVER_POSITION_M[i])
                OBSERVER_POSITION_M = builder.EndVector()
        if self.OBSERVER_VELOCITY_M_PER_S is not None:
            if np is not None and type(self.OBSERVER_VELOCITY_M_PER_S) is np.ndarray:
                OBSERVER_VELOCITY_M_PER_S = builder.CreateNumpyVector(self.OBSERVER_VELOCITY_M_PER_S)
            else:
                SKQStartOBSERVER_VELOCITY_M_PER_SVector(builder, len(self.OBSERVER_VELOCITY_M_PER_S))
                for i in reversed(range(len(self.OBSERVER_VELOCITY_M_PER_S))):
                    builder.PrependFloat64(self.OBSERVER_VELOCITY_M_PER_S[i])
                OBSERVER_VELOCITY_M_PER_S = builder.EndVector()
        if self.BAND_ID is not None:
            BAND_ID = builder.CreateString(self.BAND_ID)
        if self.COLOR_BLUE_BAND_ID is not None:
            COLOR_BLUE_BAND_ID = builder.CreateString(self.COLOR_BLUE_BAND_ID)
        if self.COLOR_RED_BAND_ID is not None:
            COLOR_RED_BAND_ID = builder.CreateString(self.COLOR_RED_BAND_ID)
        if self.LAYER_ID is not None:
            LAYER_ID = builder.CreateString(self.LAYER_ID)
        if self.BAND_IDS is not None:
            BAND_IDSlist = []
            for i in range(len(self.BAND_IDS)):
                BAND_IDSlist.append(builder.CreateString(self.BAND_IDS[i]))
            SKQStartBAND_IDSVector(builder, len(self.BAND_IDS))
            for i in reversed(range(len(self.BAND_IDS))):
                builder.PrependUOffsetTRelative(BAND_IDSlist[i])
            BAND_IDS = builder.EndVector()
        if self.DETECTIONS is not None:
            SKQStartDETECTIONSVector(builder, len(self.DETECTIONS))
            for i in reversed(range(len(self.DETECTIONS))):
                self.DETECTIONS[i].Pack(builder)
            DETECTIONS = builder.EndVector()
        if self.TRACKS is not None:
            SKQStartTRACKSVector(builder, len(self.TRACKS))
            for i in reversed(range(len(self.TRACKS))):
                self.TRACKS[i].Pack(builder)
            TRACKS = builder.EndVector()
        if self.POINTINGS is not None:
            SKQStartPOINTINGSVector(builder, len(self.POINTINGS))
            for i in reversed(range(len(self.POINTINGS))):
                self.POINTINGS[i].Pack(builder)
            POINTINGS = builder.EndVector()
        SKQStart(builder)
        if self.QUERY_ID is not None:
            SKQAddQUERY_ID(builder, QUERY_ID)
        SKQAddQUERY_KIND(builder, self.QUERY_KIND)
        SKQAddEPOCH_JD_TT(builder, self.EPOCH_JD_TT)
        SKQAddEPOCH_JD_TT_FRACTION(builder, self.EPOCH_JD_TT_FRACTION)
        if self.OBSERVER_ID is not None:
            SKQAddOBSERVER_ID(builder, OBSERVER_ID)
        if self.OBSERVER_POSITION_M is not None:
            SKQAddOBSERVER_POSITION_M(builder, OBSERVER_POSITION_M)
        if self.OBSERVER_VELOCITY_M_PER_S is not None:
            SKQAddOBSERVER_VELOCITY_M_PER_S(builder, OBSERVER_VELOCITY_M_PER_S)
        SKQAddPLACE(builder, self.PLACE)
        if self.BAND_ID is not None:
            SKQAddBAND_ID(builder, BAND_ID)
        SKQAddMAG_LIMIT(builder, self.MAG_LIMIT)
        SKQAddMAX_RESULTS(builder, self.MAX_RESULTS)
        SKQAddTILE_ORDER(builder, self.TILE_ORDER)
        SKQAddCOLOR_ENCODING(builder, self.COLOR_ENCODING)
        if self.COLOR_BLUE_BAND_ID is not None:
            SKQAddCOLOR_BLUE_BAND_ID(builder, COLOR_BLUE_BAND_ID)
        if self.COLOR_RED_BAND_ID is not None:
            SKQAddCOLOR_RED_BAND_ID(builder, COLOR_RED_BAND_ID)
        if self.LAYER_ID is not None:
            SKQAddLAYER_ID(builder, LAYER_ID)
        if self.BAND_IDS is not None:
            SKQAddBAND_IDS(builder, BAND_IDS)
        SKQAddRA_DEG(builder, self.RA_DEG)
        SKQAddDEC_DEG(builder, self.DEC_DEG)
        SKQAddRADIUS_DEG(builder, self.RADIUS_DEG)
        SKQAddHALF_WIDTH_DEG(builder, self.HALF_WIDTH_DEG)
        SKQAddHALF_HEIGHT_DEG(builder, self.HALF_HEIGHT_DEG)
        SKQAddROLL_DEG(builder, self.ROLL_DEG)
        if self.DETECTIONS is not None:
            SKQAddDETECTIONS(builder, DETECTIONS)
        SKQAddTOLERANCE_ARCSEC(builder, self.TOLERANCE_ARCSEC)
        SKQAddMAX_FIELD_DEG(builder, self.MAX_FIELD_DEG)
        if self.TRACKS is not None:
            SKQAddTRACKS(builder, TRACKS)
        if self.POINTINGS is not None:
            SKQAddPOINTINGS(builder, POINTINGS)
        SKQAddEXCLUSION_RADIUS_DEG(builder, self.EXCLUSION_RADIUS_DEG)
        SKQAddMAG_THRESHOLD(builder, self.MAG_THRESHOLD)
        SKQ = SKQEnd(builder)
        return SKQ
